with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MD_OCCUPATION as OCCUPATION_DESCRIPTION
        , cast(null as varchar) as MARITAL_STATUS
        , 'BA_HCP_PROD_8428_GPG_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8428_gpg_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MD_OCCUPATION as OCCUPATION_DESCRIPTION
        , cast(null as varchar) as MARITAL_STATUS
        , 'BA_HCP_PROD_8432_ECP_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8432_ecp_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MD_OCCUPATION as OCCUPATION_DESCRIPTION
        , cast(null as varchar) as MARITAL_STATUS
        , 'BA_HCP_PROD_8433_FHC_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8433_fhc_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MD_OCCUPATION as OCCUPATION_DESCRIPTION
        , cast(null as varchar) as MARITAL_STATUS
        , 'BA_HCP_PROD_8439_CLH_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8439_clh_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_NO))) as HUB_PARTY_HK
        , cast(null as varchar) as OCCUPATION_DESCRIPTION
        , MARITAL_STATUS_NAME as MARITAL_STATUS
        , 'BJAZ_REMEDINET_PATIENT_DETAILS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_remedinet_patient_details') }}
    where (nullif('MEMBER:' || nullif(trim(MEMBER_NO),''), 'MEMBER:')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then OCCUPATION_DESCRIPTION end) as OCCUPATION_DESCRIPTION,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MARITAL_STATUS end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then MARITAL_STATUS end)) as MARITAL_STATUS,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when OCCUPATION_DESCRIPTION is not null or MARITAL_STATUS is not null
                     then md5(upper(coalesce(cast(OCCUPATION_DESCRIPTION as varchar), '') || '|' || coalesce(cast(MARITAL_STATUS as varchar), '')))
                end as SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS_HASHDIFF is not null
